/* ===== 挂载入口（预编译产物，无 Babel 依赖） ===== */
(function mountOrError() {
  function showError() {
    var loader = document.getElementById('app-loader');
    if (!loader) return;
    loader.innerHTML =
      '<div style="text-align:center;padding:20px;line-height:1.7;">' +
      '<div style="font-size:18px;color:#ff6b6b;margin-bottom:12px;letter-spacing:2px;">加载遇到问题</div>' +
      '<div style="font-size:13px;opacity:0.6;letter-spacing:1px;">请刷新页面重试</div>' +
      '</div>';
  }
  function doMount() {
    try {
      var root = document.getElementById('root');
      if (!root || !window.App) { showError(); return; }
      ReactDOM.createRoot(root).render(React.createElement(window.App));
      var loader = document.getElementById('app-loader');
      if (loader) loader.classList.add('hidden');
    } catch (e) {
      console.error('Mount error:', e);
      showError();
    }
  }
  function loadData(cb) {
    var done = false;
    var finish = function () { if (!done) { done = true; cb(); } };
    try {
      fetch("/api/works").then(function (r) {
        return r.ok ? r.json() : Promise.reject(r.status);
      }).then(function (data) {
        try {
          var works = (data && data.works) || [];
          for (var i = 0; i < works.length && i < WORKS_INFO.length; i++) {
            var w = works[i];
            if (!w) continue;
            if (w.title) WORKS_INFO[i].title = w.title;
            if (w.author) WORKS_INFO[i].author = w.author;
            if (w.category) WORKS_INFO[i].category = w.category;
            if (w.desc) WORKS_INFO[i].desc = w.desc;
            if (w.theme || w.source || (w.team && w.team.length) || (w.process && w.process.length) || w.link) {
              WORKS_INFO[i].detail = {
                theme: w.theme || "",
                source: w.source || "",
                team: w.team || [],
                process: w.process || [],
                link: w.link || ""
              };
            }
            if (w.cover && typeof w.cover === "string" && w.cover.indexOf("wall:") !== 0 && w.cover.indexOf("data:") !== 0) {
              WALL_IMAGES[i] = w.cover;
            }
          }
        } catch (e) {
          console.warn("works merge error:", e);
        }
        finish();
      }).catch(function () { finish(); });
      setTimeout(finish, 4000);
    } catch (e) {
      finish();
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { loadData(doMount); });
  } else {
    loadData(doMount);
  }
  setTimeout(function () {
    var loader = document.getElementById('app-loader');
    if (loader && !loader.classList.contains('hidden')) showError();
  }, 8000);
})();

